<script>
$(function(){var $table=$('#payment-vouchers-table'),text=$.fn.dataTable.render.text();var dt=$table.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:$table.data('url'),order:[[2,'desc']],buttons:[window.erpExcelButton($table)],columns:[{data:'document_number',name:'finance_payment_vouchers.document_number',render:text.display},{data:'type_label',name:'finance_payment_vouchers.voucher_type',render:text.display},{data:'date_label',name:'finance_payment_vouchers.document_date',render:text.display},{data:'party_label',name:'parties.code',render:text.display},{data:'bank_label',name:'bank_accounts.code',render:text.display},{data:'amount',name:'finance_payment_vouchers.amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status',name:'finance_payment_vouchers.status',render:function(v,t){if(t!=='display')return v;var c={DRAFT:'app-status-neutral',SUBMITTED:'app-status-info',APPROVED:'app-status-success',VOID:'app-status-danger'};var l={DRAFT:'ร่าง',SUBMITTED:'รออนุมัติ',APPROVED:'อนุมัติแล้ว',VOID:'ยกเลิก'};return '<span class="badge '+(c[v]||'app-status-neutral')+'">'+text.display(l[v]||v)+'</span>';}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(v,t,r){if(t!=='display')return '';var a=['<a class="btn btn-sm btn-app-soft" href="'+text.display(r.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>'];if(r.submit_url)a.push('<button class="btn btn-sm btn-app-soft js-voucher-action" title="ส่งอนุมัติ" aria-label="ส่งอนุมัติ" data-url="'+text.display(r.submit_url)+'"><i class="bx bx-send" aria-hidden="true"></i></button>');if(r.approve_url)a.push('<button class="btn btn-sm btn-app-soft js-voucher-action" title="อนุมัติ" aria-label="อนุมัติ" data-url="'+text.display(r.approve_url)+'"><i class="bx bx-check" aria-hidden="true"></i></button>');if(r.settle_url)a.push('<button class="btn btn-sm btn-app-soft js-voucher-action" title="สร้าง Settlement" aria-label="สร้าง Settlement" data-url="'+text.display(r.settle_url)+'" data-method="POST"><i class="bx bx-transfer" aria-hidden="true"></i></button>');if(r.void_url)a.push('<button class="btn btn-sm btn-outline-danger js-voucher-action" title="ยกเลิก" aria-label="ยกเลิก" data-url="'+text.display(r.void_url)+'"><i class="bx bx-x" aria-hidden="true"></i></button>');return a.join(' ');}}]}));$(document).on('click','.js-voucher-action',function(){var b=$(this);if(b.data('submitting'))return;b.data('submitting',1).prop('disabled',true);$.ajax({url:b.data('url'),method:b.data('method')||'PUT',data:{_token:$('meta[name="csrf-token"]').attr('content')}}).done(function(r){Swal.fire({icon:r.status?'success':'error',text:r.msg}).then(function(){if(r.redirect)window.location=r.redirect;else dt.ajax.reload(null,false);});}).fail(function(x){Swal.fire({icon:'error',text:x.responseJSON?.message||x.responseJSON?.errors?.voucher?.[0]||'ไม่สามารถดำเนินการได้'});}).always(function(){b.data('submitting',0).prop('disabled',false);});});});
</script>
